  'help.send': 'Nosūtīt Biļeti',
  'help.ticketSent': 'Biļete Nosūtīta!',
  'help.ticketSentDesc': 'Esam saņēmuši tavu pieprasījumu. Mūsu komanda atbildēs pa e-pastu 24 stundu laikā.',
  'help.close': 'Aizvērt',
  'help.ticketError': 'Neizdevās nosūtīt biļeti. Mēģini vēlreiz.',
  'help.type.cant_login': 'Nevaru pieslēgties',
  'help.type.email_issue': 'Problēma ar e-pastu',
  'help.type.security': 'Drošība',
  'help.type.other': 'Cits',
  'help.faq.cantLogin.q': 'Nevaru piekļūt savai kontam',
  'help.faq.cantLogin.a': 'Pārliecinies, ka izmanto pareizo e-pastu un paroli. Ja esi aizmirsis paroli, klikšķini uz "Aizmirsāt paroli?" pieteikšanās ekrānā. Ja problēma turpinās, izveido atbalsta biļeti.',
  'help.faq.notReceiving.q': 'Nesaņemu e-pastus',
  'help.faq.notReceiving.a': 'Vispirms pārbaudi Spam mapi. Pārliecinies, ka tavs krātuves apjoms nav pilns. Ja problēma turpinās, apstiprini, ka sūtītājs ir ar pareizo adresi un izveido biļeti.',
  'help.faq.cantSend.q': 'Nevaru nosūtīt e-pastus',
  'help.faq.cantSend.a': 'Pārbaudi savu interneta savienojumu un vai saņēmēja adrese ir pareiza. Pārliecinies, ka pielikumi nepārsniedz 25MB. Mēģini vēlreiz pēc dažām minūtēm.',
  'help.faq.forgotPassword.q': 'Aizmirsu savu paroli',
  'help.faq.forgotPassword.a': 'Pieteikšanās ekrānā klikšķini uz "Aizmirsāt paroli?" un seko norādījumiem, lai atiestatītu savu paroli, izmantojot atjaunošanas e-pastu.',
  'help.faq.accountSecurity.q': 'Domāju, ka mans konts ir apdraudēts',
  'help.faq.accountSecurity.a': 'Nekavējoties maini savu paroli. Pārbaudi Sūtītās ziņas, ko neesi nosūtījis. Ieslēdz divu faktoru autentifikāciju Iestatījumos > Drošība. Ja nepieciešams, izveido steidzamu biļeti.',
  'help.faq.appAccess.q': 'Kā piekļūt lietotnei mobilajā telefonā?',
  'help.faq.appAccess.a': 'Tu vari piekļūt Chatyy caur pārlūkprogrammu chatyy.com.br, vai lejupielādēt mūsu lietotni no sava ierīces lietotņu veikala.',
  'privacy.title': 'Privātuma Politika',
  'privacy.subtitle': 'Kā mēs aizsargājam un apstrādājam tavus datus',
  'privacy.lastUpdated': 'Pēdējā atjaunināšana: 2026. gada marts',
  'privacy.dataCollection.title': 'Datu Vākšana',
  'privacy.dataCollection.body': 'Mēs vācam tikai nepieciešamo informāciju e-pasta pakalpojumam: tavs vārds, e-pasta adrese un nosūtīto un saņemto ziņu saturs. Mēs nepārdodam un neizplatinām tavus personas datus trešajām personām mārketinga nolūkos.',
  'privacy.dataUsage.title': 'Kā Mēs Izmantojam Tavu Datus',
  'privacy.dataUsage.body': 'Tavi dati tiek izmantoti tikai, lai darbinātu un uzlabotu e-pasta pakalpojumu, tostarp ziņu piegādi, surogātpasta filtrēšanu, AI funkcijas (ar tavu piekrišanu) un konta drošību.',
  'privacy.dataSecurity.title': 'Datu Drošība',
  'privacy.dataSecurity.body': 'Mēs izmantojam nozares standarta šifrēšanu (TLS/SSL) visiem datiem pārsūtīšanas un uzglabāšanas laikā. Sesijas tiek aizsargātas ar šifrētiem tokeniem un CSRF aizsardzību. Mēs regulāri pārbaudām mūsu drošības praksi.',
  'privacy.cookies.title': 'Sīkdatnes un Vietējā Uzglabāšana',
  'privacy.cookies.body': 'Mēs izmantojam būtiskas sīkdatnes un vietējo uzglabāšanu, lai saglabātu tavu sesiju, atcerētos tavas preferences (tēma, valoda) un nodrošinātu plūstošu pieredzi. Mēs neizmantojam trešo pušu izsekošanas sīkdatnes.',
  'privacy.thirdParties.title': 'Trešo Pušu Pakalpojumi',
  'privacy.thirdParties.body': 'Mēs varam izmantot trešo pušu pakalpojumus specifiskām funkcionalitātēm, piemēram, AI (Anthropic Claude) un push paziņojumiem. Šie pakalpojumi ievēro savas privātuma politikas un apstrādā tikai minimālo nepieciešamo datu apjomu.',
  'privacy.rights.title': 'Tavi Tiesības',
  'privacy.rights.body': 'Tev ir tiesības piekļūt, labot, eksportēt vai dzēst savus personas datus jebkurā laikā. Tu vari pārvaldīt savus datus Iestatījumos vai sazinoties ar mūsu atbalstu.',
  'privacy.contact.title': 'Sazinies ar Mums',
  'privacy.contact.body': 'Par privātuma jautājumiem vai datu pieprasījumiem, lūdzu, sazinies pa privacy@chatyy.com.br. Mēs atbildēsim 30 dienu laikā.',
  'terms.title': 'Pakalpojumu Noteikumi',
  'terms.subtitle': 'Chatyy lietošanas vadlīnijas',
  'terms.lastUpdated': 'Pēdējā atjaunināšana: 2026. gada marts',
  'terms.acceptance.title': 'Noteikumu Pieņemšana',
  'terms.acceptance.body': 'Piekļūstot vai izmantojot Chatyy, tu piekrīti šiem Pakalpojumu Noteikumiem. Ja nepiekrīti kādai no šīm daļām, nelieto šo pakalpojumu.',
  'terms.services.title': 'Pakalpojumu Apraksts',
  'terms.services.body': 'Chatyy nodrošina e-pasta komunikācijas pakalpojumus, tostarp e-pastu sūtīšanu, saņemšanu un pārvaldību, kā arī AI funkcijas, kalendāra integrāciju un videokonferences.',
  'terms.accounts.title': 'Lietotāju Konti',
  'terms.accounts.body': 'Tu esi atbildīgs par savu akreditācijas datu drošību. Neizplati savu paroli un nepieļauj nesankcionētu piekļuvi savai kontam. Tev jābūt vismaz 13 gadus vecam, lai izmantotu šo pakalpojumu.',
  'terms.conduct.title': 'Pieņemama Lietošana',
  'terms.conduct.body': 'Tu piekrīti nelietot pakalpojumu, lai sūtītu surogātpastu, ļaunprātīgu programmatūru, phishing vai jebkuru nelikumīgu saturu. Nemēģini piekļūt citu lietotāju kontiem vai traucēt pakalpojuma infrastruktūru.',
  'terms.content.title': 'Satura Īpašums',
  'terms.content.body': 'Tu saglabā īpašumtiesības uz visu saturu, ko izveido un nosūti, izmantojot pakalpojumu. Mēs neizvirzām prasības uz taviem e-pastiem vai pielikumiem. Mēs varam apstrādāt saturu, kā nepieciešams, lai nodrošinātu pakalpojumu.',
  'terms.limitation.title': 'Atbildības Ierobežojums',
  'terms.limitation.body': 'Chatyy tiek nodrošināts "kā ir". Mēs cenšamies nodrošināt 99,9% pieejamību, bet negarantējam nepārtrauktu pakalpojumu. Mēs neesam atbildīgi par netiešiem, nejaušiem vai sekas izrietošiem zaudējumiem, kas radušies pakalpojuma lietošanas dēļ.',
  'terms.termination.title': 'Kontu Slēgšana',
  'terms.termination.body': 'Mēs varam apturēt vai slēgt kontus, kas pārkāpj šos noteikumus. Tu vari dzēst savu kontu jebkurā laikā Iestatījumos. Pēc slēgšanas tavi dati tiks dzēsti 30 dienu laikā.',
  'terms.changes.title': 'Izmaiņas Noteikumos',
  'terms.changes.body': 'Mēs varam periodiski atjaunināt šos noteikumus. Mēs informēsim par būtiskām izmaiņām pa e-pastu vai paziņojumu lietotnē. Turpmāka lietošana pēc izmaiņām tiek uzskatīta par piekrišanu atjauninātajiem noteikumiem.',
