  'plans.faqWhatIsPlusAnswer': 'Tas ir Chatyy premium plāns, kas aizsargā visas jūsu sarunas, fotoattēlus un video. Ar Chatyy One, pat ja jūs nejauši izdzēsīsiet kaut ko, varat atgūt to līdz 30 dienām. Turklāt jūs iegūstat 200GB krātuves, One AI kā personīgo asistenti un varat sūtīt failus līdz 100MB.',
